/* argo-htmx-shim v0.1 — minimal HTMX-compatible shim
 *
 * Implements the subset needed by the argo dashboard:
 *   - hx-get, hx-post: send the request, swap response into hx-target
 *     (defaults to closest section/element with hx-get).
 *   - hx-trigger="load" — fire on page load.
 *   - hx-trigger="every Ns" — repeat with N seconds interval.
 *   - hx-trigger="click" (default for buttons) — fire on click.
 *   - hx-swap: "innerHTML" (default) | "outerHTML".
 *   - hx-target: CSS selector for the element to swap; default = self.
 *
 * Substitute the real htmx.min.js (v1.9.10 pinned) when bundled —
 * attribute names + semantics match. No external CDN; ~70 LOC. */
(function () {
  'use strict';
  function $$(sel, root) { return Array.from((root || document).querySelectorAll(sel)); }
  function target(el) {
    var sel = el.getAttribute('hx-target');
    if (!sel) return el;
    if (sel === 'this') return el;
    return document.querySelector(sel) || el;
  }
  function swap(el, html) {
    var mode = el.getAttribute('hx-swap') || 'innerHTML';
    var t = target(el);
    if (mode === 'outerHTML') {
      var tmp = document.createElement('div');
      tmp.innerHTML = html;
      var node = tmp.firstElementChild;
      if (node) t.replaceWith(node);
    } else {
      t.innerHTML = html;
    }
    bind(t);
  }
  function send(el, method, url, body) {
    var xhr = new XMLHttpRequest();
    xhr.open(method, url, true);
    if (body) xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
    xhr.onreadystatechange = function () {
      if (xhr.readyState !== 4) return;
      if (xhr.status >= 200 && xhr.status < 300) swap(el, xhr.responseText);
      else swap(el, '<p class="muted">Error: ' + xhr.status + '</p>');
    };
    xhr.send(body || null);
  }
  function fire(el) {
    var url = el.getAttribute('hx-get') || el.getAttribute('hx-post');
    if (!url) return;
    var method = el.hasAttribute('hx-post') ? 'POST' : 'GET';
    send(el, method, url, null);
  }
  function parseTrigger(spec) {
    spec = (spec || '').trim();
    var triggers = spec.split(',').map(function (s) { return s.trim(); });
    var out = { load: false, click: false, every: 0 };
    triggers.forEach(function (t) {
      if (t === 'load') out.load = true;
      else if (t === 'click') out.click = true;
      else {
        var m = /^every\s+(\d+)\s*s$/.exec(t);
        if (m) out.every = parseInt(m[1], 10) * 1000;
      }
    });
    return out;
  }
  function bind(root) {
    $$('[hx-get], [hx-post]', root).forEach(function (el) {
      if (el.__hxBound) return;
      el.__hxBound = true;
      var trig = parseTrigger(el.getAttribute('hx-trigger'));
      var isButton = el.tagName === 'BUTTON' || el.tagName === 'A';
      if (trig.load) fire(el);
      if (trig.every) setInterval(function () { fire(el); }, trig.every);
      if (trig.click || (!trig.load && !trig.every && isButton)) {
        el.addEventListener('click', function (ev) { ev.preventDefault(); fire(el); });
      }
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { bind(document); });
  } else {
    bind(document);
  }
})();
